### cot
1. Iterate through each JSON file in the given directory.
2. For each file, load the JSON data and recursively extract all keys from the nested structures.
3. Count the occurrences of each key across all files.
4. Return a dictionary with keys as keys and their total counts as values.

### code
```python
import collections
import json
import os

def task_func(directory_path: str) -> dict:
    key_counts = collections.defaultdict(int)
    for filename in os.listdir(directory_path):
        if filename.endswith('.json'):
            file_path = os.path.join(directory_path, filename)
            with open(file_path, 'r') as f:
                try:
                    data = json.load(f)
                except json.JSONDecodeError:
                    continue
                stack = [data]
                while stack:
                    current = stack.pop()
                    if isinstance(current, dict):
                        for key in current:
                            key_counts[key] += 1
                            stack.append(current[key])
                    elif isinstance(current, list):
                        stack.extend(current)
    return dict(key_counts)
```

