import re
import urllib.request
import json
IP_REGEX = r'[0-9]+(?:\.[0-9]+){3}'
def task_func(API_URL):
    try:
        with urllib.request.urlopen(API_URL) as response:
            html = response.read().decode('utf-8')
            match = re.search(IP_REGEX, html)
            if match:
                return match.group()
            else:
                return ""
    except Exception as e:
        return str(e)
