import json
import re
import pandas as pd
def task_func(json_str):
    try:
        data = json.loads(json_str)
    except:
        return pd.DataFrame()
    result = {}
    for k, v in data.items():
        if isinstance(v, (int, float)):
            result[k] = v * 2
        elif isinstance(v, list):
            new_list = []
            for item in v:
                if isinstance(item, (int, float)):
                    new_list.append(item * 2)
                elif isinstance(item, str):
                    matches = re.findall(r'[-+]?\d*\.?\d+', item)
                    if matches:
                        num = float(matches[0]) if '.' in matches[0] else int(matches[0])
                        new_list.append(num * 2)
                    else:
                        new_list.append(item)
                else:
                    new_list.append(item)
            result[k] = new_list
        elif isinstance(v, str):
            matches = re.findall(r'[-+]?\d*\.?\d+', v)
            if matches:
                num = float(matches[0]) if '.' in matches[0] else int(matches[0])
                result[k] = num * 2
            else:
                result[k] = v
        else:
            result[k] = v
    df = pd.DataFrame(result, index=[0]) if result else pd.DataFrame()
    return df
