1. Parse the JSON string to obtain a Python data structure.
2. Recursively traverse the data, removing any `None` values and replacing email addresses with the placeholder "None".
3. Count the frequency of each unique value in the processed data.
4. Return a dictionary containing the processed data under the key "data" and the value counts under the key "value_counts".

### code
```python
import json
import re
from collections import Counter

REPLACE_NONE = "None"
EMAIL_PATTERN = r'\b[\w\.-]+@[\w\.-]+\.\w+\b'

def task_func(json_str):
    def process(item):
        if isinstance(item, dict):
            return {k: process(v) for k, v in item.items() if v is not None}
        elif isinstance(item, list):
            return [process(i) for i in item if i is not None]
        elif isinstance(item, str):
            return re.sub(EMAIL_PATTERN, REPLACE_NONE, item)
        else:
            return item

    data = json.loads(json_str)
    processed = process(data)

    def collect_values(obj, values):
        if isinstance(obj, dict):
            for v in obj.values():
                collect_values(v, values)
        elif isinstance(obj, list):
            for i in obj:
                collect_values(i, values)
        else:
            values.append(obj)

    all_values = []
    collect_values(processed, all_values)
    value_counts = Counter(all_values)

    return {"data": processed, "value_counts": value_counts}
